(() => {
  const cfg = () => window.AS_SERVICIOS_CONFIG || {};
  const configured = () => {
    const u = String(cfg().API_URL || "");
    return /^https:\/\/script\.google\.com\/macros\/s\//.test(u) && /\/exec(?:$|\?)/.test(u);
  };

  const wait = ms => new Promise(resolve => setTimeout(resolve, ms));

  async function request(url, options = {}) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), Number(cfg().REQUEST_TIMEOUT_MS || 25000));
    try {
      const res = await fetch(url, {...options, signal: ctrl.signal, redirect: "follow", cache: "no-store"});
      if (!res.ok) throw new Error(`HTTP_${res.status}`);
      const json = await res.json();
      if (json && json.ok === false) throw new Error(json.error || "API_ERROR");
      return json;
    } finally { clearTimeout(timer); }
  }

  // Lecturas por JSONP: compatibles con GitHub Pages + Apps Script.
  function jsonp(action, data = {}, timeoutMs = Number(cfg().REQUEST_TIMEOUT_MS || 25000)) {
    if (!configured()) return Promise.reject(new Error("API_NO_CONFIGURADA"));
    return new Promise((resolve, reject) => {
      const cb = `__as_cb_${Date.now()}_${Math.random().toString(36).slice(2)}`;
      const script = document.createElement("script");
      script.referrerPolicy = "no-referrer";
      let done = false;
      const cleanup = (err, value) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        try { delete window[cb]; } catch (_) { window[cb] = undefined; }
        script.remove();
        if (err) reject(err); else resolve(value);
      };
      const timer = setTimeout(() => cleanup(new Error("API_TIMEOUT")), Number(timeoutMs || 25000));
      window[cb] = payload => {
        if (payload && payload.ok === false) cleanup(new Error(payload.error || "API_ERROR"));
        else cleanup(null, payload);
      };
      script.onerror = () => cleanup(new Error("API_SCRIPT_LOAD_ERROR"));
      const url = new URL(cfg().API_URL);
      url.searchParams.set("action", action);
      url.searchParams.set("callback", cb);
      url.searchParams.set("payload", JSON.stringify(data || {}));
      url.searchParams.set("_", String(Date.now()));
      script.src = url.toString();
      document.head.appendChild(script);
    });
  }

  // Escrituras robustas por POST en iframe + confirmación independiente por request_id.
  // Evita falsos errores cuando Apps Script alcanza a guardar pero el navegador tarda en recibir la respuesta.
  function iframePost(action, data = {}) {
    if (!configured()) return Promise.reject(new Error("API_NO_CONFIGURADA"));
    return new Promise((resolve, reject) => {
      const requestId = `ASREQ_${Date.now()}_${Math.random().toString(36).slice(2)}`;
      const iframeName = `as_api_frame_${requestId.replace(/[^a-z0-9_]/gi, "")}`;
      const iframe = document.createElement("iframe");
      iframe.name = iframeName;
      iframe.style.cssText = "position:fixed;width:1px;height:1px;opacity:0;pointer-events:none;border:0;left:-9999px;top:-9999px";
      iframe.setAttribute("aria-hidden", "true");

      const form = document.createElement("form");
      form.method = "POST";
      form.action = cfg().API_URL;
      form.target = iframeName;
      form.style.display = "none";
      form.acceptCharset = "UTF-8";

      const add = (name, value) => {
        const input = document.createElement("input");
        input.type = "hidden";
        input.name = name;
        input.value = value;
        form.appendChild(input);
      };
      add("transport", "iframe");
      add("request_id", requestId);
      add("envelope", JSON.stringify({action, data, requestId}));

      let finished = false;
      let pollTimeout = null;
      let hardTimer = null;
      const maxMs = Math.max(30000, Number(cfg().WRITE_CONFIRM_TIMEOUT_MS || 45000));
      const statusTimeout = Math.max(4000, Number(cfg().STATUS_TIMEOUT_MS || 8000));
      const started = Date.now();

      const finish = (err, value) => {
        if (finished) return;
        finished = true;
        clearTimeout(pollTimeout);
        clearTimeout(hardTimer);
        window.removeEventListener("message", onMessage);
        setTimeout(() => { iframe.remove(); form.remove(); }, 80);
        if (err) {
          err.requestId = requestId;
          reject(err);
        } else resolve(value);
      };

      const handleResult = payload => {
        if (payload && payload.ok === false) finish(new Error(payload.error || "API_ERROR"));
        else finish(null, payload || {ok:true});
      };

      const onMessage = event => {
        const msg = event && event.data;
        if (!msg || msg.source !== "SERVICIOS_INFORMATICOS_AS_API" || msg.requestId !== requestId) return;
        handleResult(msg.payload);
      };

      const poll = async () => {
        if (finished) return;
        try {
          const st = await jsonp("requestStatus", {request_id:requestId}, statusTimeout);
          if (st && st.pending === false) return handleResult(st.result || {ok:true});
        } catch (_) {
          // Una consulta de confirmación puede fallar temporalmente; se vuelve a intentar.
        }
        if (finished) return;
        if (Date.now() - started >= maxMs) {
          const err = new Error("API_CONFIRMATION_TIMEOUT");
          err.requestId = requestId;
          return finish(err);
        }
        pollTimeout = setTimeout(poll, 1200);
      };

      hardTimer = setTimeout(() => {
        const err = new Error("API_CONFIRMATION_TIMEOUT");
        err.requestId = requestId;
        finish(err);
      }, maxMs + 2500);

      window.addEventListener("message", onMessage);
      document.body.appendChild(iframe);
      document.body.appendChild(form);
      form.submit();
      pollTimeout = setTimeout(poll, 650);
    });
  }

  async function lookupPublicRequest(clientRequestId, attempts = 8) {
    const id = String(clientRequestId || "");
    if (!id) return null;
    for (let i = 0; i < attempts; i++) {
      try {
        const result = await jsonp("requestLookup", {client_request_id:id}, Number(cfg().STATUS_TIMEOUT_MS || 8000));
        if (result && result.found && result.verified) return result;
      } catch (_) {}
      if (i < attempts - 1) await wait(1400);
    }
    return null;
  }

  window.AleAPI = {
    configured,
    async get(action, params = {}) { return jsonp(action, params); },
    async post(action, data = {}, token = "") {
      const payload = token ? {...(data || {}), __token: token} : (data || {});
      return iframePost(action, payload);
    },
    async submitPublic(action, data = {}) {
      // TODA escritura pública usa POST + confirmación. No usamos GET para crear registros.
      return iframePost(action, data);
    },
    async lookupPublicRequest(clientRequestId, attempts = 8) {
      return lookupPublicRequest(clientRequestId, attempts);
    },
    async health() { return jsonp("health", {}); },
    fileToDataUrl(file) {
      return new Promise((resolve,reject)=>{
        const r = new FileReader();
        r.onload = () => resolve(r.result);
        r.onerror = reject;
        r.readAsDataURL(file);
      });
    }
  };
})();
